"""Native Workspace recovery area. No third-party requests or embedded research."""
SCRIPT = r'''const base='/v1/private-research/recovery', el=id=>document.getElementById(id);let state;
async function request(path,body,intent){const response=await fetch(base+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-Recovery-Intent':intent}:{},body:body?JSON.stringify(body):undefined});if(!response.ok)throw new Error(response.status===403?'Recovery authorization is missing, expired or this action is disabled.':'Recovery request could not be verified ('+response.status+').');return response.json()}
async function load(){try{state=await request('/area-status');el('status').textContent=state.state==='NOT_CREATED'?'The private research area has not been created.':'Private Workspace research area · revision '+state.revision;el('create').hidden=state.state!=='NOT_CREATED';el('create').disabled=!state.writes_enabled;el('restore').disabled=!state.writes_enabled||!state.plan;el('records').replaceChildren();el('manifest').replaceChildren();if(state.plan){const rows=state.plan.records;el('counts').textContent=(state.records||[]).length+' restored records · '+rows.filter(r=>r.classifications.includes('BLOCKED')).length+' restricted records in this authorized selection';for(const row of state.records||[]){const card=document.createElement('article'),title=document.createElement('h3'),provenance=document.createElement('p'),details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');title.textContent=row.payload.title||row.payload.schema||row.recovery_provenance.original_calculation_id;provenance.textContent='Original project '+row.recovery_provenance.original_project_id+' · calculation '+row.recovery_provenance.original_calculation_id;summary.textContent='Inspect original calculation / source metadata';pre.textContent=JSON.stringify(row.payload,null,2);details.append(summary,pre);card.append(title,provenance,details);if(row.source_blob){const a=document.createElement('a');a.href=base+'/artifacts/'+encodeURIComponent(row.source_blob.artifact_id);a.textContent='Download original '+row.source_blob.filename;card.append(a)}el('records').append(card)}for(const [id,m]of Object.entries(state.restoration_manifests||{})){const p=document.createElement('p');p.textContent=id+' · '+m.state+' · '+Object.keys(m.created_object_hashes).length+' records';el('manifest').append(p)}}}catch(error){el('status').textContent=error.message;el('status').setAttribute('role','alert')}}
el('refresh').onclick=load;el('create').onclick=async()=>{try{await request('/area',{source_project_id:state.source_project_id,target_project_id:state.target_project_id},'create-area');await load()}catch(e){el('status').textContent=e.message}};el('restore').onclick=async()=>{try{await request('/restore',{source_project_id:state.source_project_id,target_project_id:state.target_project_id,plan_sha256:state.plan.plan_sha256,expected_revision:state.revision},'restore');await load()}catch(e){el('status').textContent=e.message}};load();'''
HTML = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Private research restoration | Workspace</title><style>body{margin:0;background:#0d1516;color:#e7eeeb;font:16px/1.6 system-ui}main{max-width:1080px;margin:auto;padding:32px 24px}h1{font-size:36px}section,article{border:1px solid #38534b;border-radius:10px;padding:20px;margin:20px 0}.notice{background:#28241a;border-left:3px solid #d5b577;padding:16px}a{color:#b3e3d4}button{background:#c4e9dc;color:#142820;border:0;padding:12px 18px;border-radius:6px;margin:8px;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}h3{overflow-wrap:anywhere}p{overflow-wrap:anywhere}</style></head><body><main><p>SUSTAINABLE CATALYST / WORKSPACE</p><h1>Private research restoration</h1><p class="notice">Original records and owner identities are preserved. Scientific validity is not reassessed by restoration. Unresolved ownership, environment mappings and development records remain restricted. Publication is disabled.</p><p id="status" role="status" aria-live="polite">Checking your authorized research area…</p><p id="counts"></p><button id="refresh">Refresh</button><button id="create" hidden disabled>Create private research area</button><button id="restore" disabled>Restore approved eligible records</button><section><h2>Research, calculations and evidence</h2><div id="records"></div></section><section><h2>Restoration history</h2><div id="manifest"></div></section><section><h2>Existing research tools</h2><p>These links open existing tools. They do not transfer records, execute calculations or verify scientific results.</p><p><a href="https://workbench.sustainablecatalyst.com">Workbench and existing reporting</a> · <a href="https://library.sustainablecatalyst.com">Knowledge Library</a> · <a href="https://sustainablecatalyst.com/lab/">Research Lab</a> · <a href="https://intelligence.sustainablecatalyst.com">Site Intelligence</a></p></section><p><a href="/v1/private-research/ui">Back to private Workspace</a></p></main><script>''' + SCRIPT + '''</script></body></html>'''
